"""NNE req5144: CV including motivation; no photo or separate cover letter."""
import os
from master_design import MasterDoc
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
NAME='SHAHRAM AJLOO';TITLE='Director · PLC Systems, Automation, Robotics & AI';CONTACT='+45 93 99 95 14 · ajlooshahram@gmail.com · linkedin.com/in/shahramajloo · Måløv, Denmark'
def build(path):
 m=MasterDoc(os.path.join(ROOT,'Shahram_Ajloo_NNE_DepartmentManagerEI.docx'),lang='en-GB')
 m.header_banner(NAME,TITLE,CONTACT)
 m.section('MOTIVATION — CONNECT PEOPLE, CAPABILITY AND PROJECT DELIVERY')
 m.para('NNE’s PLC Systems department enables reliable pharmaceutical production by turning concepts into implemented systems. The opportunity is to help line managers and specialists connect project demand, competence development and a clear shared direction across Virum and Kalundborg. I am applying because the work brings together technical leadership, regulated delivery and the responsible use of automation and AI in a purpose that ultimately serves patients.',after=35)
 m.section('DIRECTION, CAPACITY, CAPABILITY — APPROACH TO THE ROLE')
 for a,b in [('Direction','Translate NNE strategy into a small set of department goals with the management team; review progress, risks and priorities with stakeholders in the CVP leadership forum.'),('Capacity','Work with project managers and line managers to match future project demand with availability, skills and development needs across both sites.'),('Capability','Coach technical specialists and lead engineers; develop PLC, automation and relevant robotics and AI capabilities with the people who deliver the work.')]:m.bullet(a,b,after=10)
 m.section('LEADERSHIP AND TECHNICAL FOUNDATION')
 m.para('More than five years of people leadership, including eight employees at ELOHVAC, 14 at Ventek-Air and 12 technicians at ARJ; coordination of 25 specialists across 37 Novo Nordisk capital projects. Experience leading industrial PLC/control-system work is confirmed, while the specific platforms, assignments and technical responsibilities need clarification. Previous leadership has been at smaller scale than NNE’s department of more than 70; the transition would require an explicit operating rhythm with 2–3 line managers and management support.',after=30)
 m.para('**Education:** B.Tech in Technology Management and Mechanical Engineering, electrical and mechanical engineering design qualification, and authorised Danish maskinmester LV/MV/HV. An M.Sc. is not documented; NNE can assess the combination of education and relevant professional experience. **On-site:** available at Virum and Kalundborg five days a week as required.',after=25)
 m.page_break();m.section('EXPERIENCE')
 jobs=[('Owner / Technical Director / authorised maskinmester','ELOHVAC ApS · Copenhagen · May 2023–present','8 employees including 3 apprentices · full P&L',[('People and operations','Lead five electricians and three apprentices through daily planning, 1:1s, training and safety follow-up; manage suppliers, costs, quality and delivery.'),('AI in operational work','Built AI-assisted estimating, scheduling, quality checklists and KPI tools, contributing to a documented productivity improvement of over 40%.')]),('Co-owner and CTO / Technical Lead, AI department','Data Power Consultant ApS · Copenhagen · 2024–Nov 2026 · alongside ELOHVAC','4–10 people · company ceased in November 2026',[('Technical leadership','Led AI and AI-coding work; delivered technical and industrial applications from requirements and architecture through integration, documentation and handover.'),('Capability and governance','Introduced AI-assisted development with review and testing standards; worked with LLM APIs and AI agents and applied AI to management reporting.')]),('Senior Commissioning Engineer / Project Manager, electrical systems','Novo Nordisk A/S · Nov 2022–Jul 2024','37 concurrent CAPEX projects · 25 specialists',[('Regulated project delivery','Coordinated engineering, procurement and construction; managed progress, budget and risk. FAT/SAT and IQ/OQ/PQ under GMP/FDA/EMA with zero critical deviations at handover.'),('Technical interfaces','Worked with electrical systems including panels, controls, UPS and emergency systems; coordinated specialist contributions and reported to management and client.')]),('Project and Workshop Manager','Ventek-Air · Jan 2022–Nov 2022','14 people · 11 concurrent projects',[('Capacity and priorities','Led daily planning, coordinated subcontractors, and used team meetings and bottleneck analysis to follow project progress.')]),('Operations and Maintenance Manager / Workshop Technician','BIOFOS, Lynetten · Aug 2017–Jan 2022','Critical 24/7 technical operations',[('Control and operational reliability','Maintained and troubleshot electrical and mechanical systems including high-voltage switchgear and SCADA; used 5S, standard work and PDCA.')]),('Electromechanical Technician / Production Team Lead','ARJ Engineering · Dec 2003–Mar 2010','12 mechanics and technicians',[('Team and technical operations','Led shift planning and material coordination; diagnosed and repaired industrial electrical and mechanical equipment.')])]
 for t,meta,scope,bullets in jobs:
  m.job(t,meta,scope=scope)
  for a,b in bullets:m.bullet(a,b,after=10)
 m.page_break();m.section('EDUCATION, METHODS AND LANGUAGES')
 for a,b in [('B.Tech, Technology Management and Mechanical Engineering','Copenhagen School of Marine and Technical Engineering · 2017–2022'),('Authorised Danish maskinmester, LV/MV/HV','Danish Safety Technology Authority · 2023'),('Electrical and mechanical engineering design, electrical engineering','Tehran Technical University · EQF 6 · 2000–2003'),('PRINCE2 certified project manager','AXELOS / PeopleCert')]:m.edu(a,b)
 m.para('**Methods and systems:** Lean and Six Sigma applied in practice, not certified; PRINCE2 certified; SAP ERP, Excel, Python, Claude API and AI-assisted tools. **Languages:** Danish and professional English, spoken and written. **Location:** available on site in Virum and Kalundborg five days a week.',after=20)
 rows=[('Lead 70+ employees through 2–3 line managers','Led smaller teams: eight people at ELOHVAC and 14 at Ventek-Air; coordinated 25 specialists at Novo. Direct leadership at NNE’s 70+ scale is not documented; agree governance and delegation with line managers.'),('CVP leadership and departmental direction','ELOHVAC: full P&L and operational priorities; Novo: management and client reporting across 37 projects. Would align goals, performance and risks with the VP and fellow directors.'),('Translate strategy into goals and performance','ELOHVAC: schedules, KPI tools and a documented productivity improvement of over 40%. Would agree department objectives and a performance rhythm with the leadership team.'),('Coach specialists, lead engineers and line managers','Regular 1:1s and training at ELOHVAC; coordination of 25 specialists at Novo. Would agree individual development priorities and provide clear decision rights and support.'),('Project resources and competence alignment','Ventek-Air: 14 people across 11 projects; Novo: 25 specialists across 37. Would review project demand, resource capacity and skill gaps with project and line managers.'),('Industrial automation, PLC and control systems','Leadership of PLC/control-system work is confirmed; the specific projects, systems and responsibility need clarification. BIOFOS experience includes SCADA and high-voltage switchgear.'),('Robotics, AI and manufacturing intelligence','Data Power: AI applications and AI-assisted development; ELOHVAC: KPI and planning tools. Specific industrial robotics leadership and manufacturing-intelligence platforms are not documented.'),('End-to-end pharma engineering and delivery','Novo: engineering, procurement and construction coordination, FAT/SAT and IQ/OQ/PQ under GMP, with zero critical deviations at handover. Full API facility ownership is not documented.'),('Empowering leadership, trust and collaboration','ELOHVAC: daily leadership and development of eight employees; Data Power: 4–10 people. Would agree expectations, listen to concerns and follow decisions through transparently.'),('Engineering education and people leadership','B.Tech in Technology Management and Mechanical Engineering and electrical engineering design qualification; no M.Sc. documented. More than five years of people leadership in technical teams.'),('Danish, English and on-site presence','Danish and professional English, written and spoken. Available for on-site work in Virum and Kalundborg five days per week as required by the role.')]
 m.models_table('ROLE NEEDS — EVIDENCE AND PROPOSED APPROACH',('Requirement','Evidence or proposed approach'),rows,widths=(2600,7746))
 m.section('INITIAL PRIORITIES WITH THE MANAGEMENT TEAM')
 for t in ['Meet line managers, specialists and project managers to understand commitments, capability gaps, people priorities and delivery risks at both sites.', 'Agree a transparent rhythm for strategy, resource allocation, competence development and escalation with the VP and department leadership.', 'Review opportunities for PLC, automation, robotics and AI with technical experts and project owners; make quality, validation and adoption explicit before committing to changes.']:m.bullet('',t,after=10)
 m.save(path)
if __name__=='__main__':
 p=os.path.join(ROOT,'Shahram_Ajloo_NNE_DirectorPLCSystems_5144.docx');build(p);print(p)
